import contextlib
import os

@contextlib.contextmanager
def temp_env(key, value):
    old = os.environ.get(key)
    os.environ[key] = value
    try:
        yield
    finally:
        if old is None:
            os.environ.pop(key, None)
        else:
            os.environ[key] = old

def record_event(event, history=None):
    if history is None:
        history = []
    history.append(event)
    return history

