solution.reference:
def article_list(request):
    articles = (
        Article.objects.filter(published=True)
        .select_related("author")
        .prefetch_related("tags")
    )
    data = [
        {
            "title": a.title,
            "author": a.author.name,
            "tags": [t.name for t in a.tags.all()],
        }
        for a in articles
    ]
    return JsonResponse({"articles": data})
